INSERT INTO disease (class_name, plant, disease_name, healthy, pathogen, description, symptoms, treatment, prevention) VALUES
('Apple___Apple_scab', 'Apple', 'Apple scab', FALSE, 'Venturia inaequalis (fungus)', 'A common fungal disease of apple trees, favored by cool and wet spring weather.', 'Olive-green to dark brown velvety spots on leaves that later turn black and scabby. Infected fruit shows dark corky lesions. Severe infections cause early leaf drop.', 'Remove and destroy fallen infected leaves. Apply a fungicide approved for apple scab from bud break during wet periods, following local recommendations.', 'Plant resistant varieties, rake or shred fallen leaves in autumn, and prune to improve air circulation.'),
('Apple___Black_rot', 'Apple', 'Black rot', FALSE, 'Botryosphaeria obtusa (fungus)', 'A fungal disease that attacks leaves, fruit and branches of apple trees.', 'On leaves, small purple spots that enlarge into brown spots with a purple border (frogeye leaf spot). Fruit rots with concentric rings and dries into black mummies. Cankers appear on branches.', 'Prune out dead wood and cankers, remove mummified fruit, and apply an approved fungicide during the growing season.', 'Keep the orchard clean, remove dead wood and mummified fruit, and avoid wounding the trees.'),
('Apple___Cedar_apple_rust', 'Apple', 'Cedar apple rust', FALSE, 'Gymnosporangium juniperi-virginianae (fungus)', 'A rust disease that needs two hosts to complete its cycle: apple trees and junipers (eastern red cedar).', 'Bright yellow-orange spots on the upper side of leaves in spring, later with small black dots. Small tube-like structures may form on the underside.', 'Apply protective fungicide sprays from the pink bud stage during infection periods, and remove rust galls from nearby junipers.', 'Plant resistant apple varieties and avoid planting apple trees near junipers.'),
('Apple___healthy', 'Apple', 'Healthy', TRUE, NULL, 'The apple leaf shows no visible sign of disease.', 'Uniform color and normal shape, with no spots, lesions, mold or deformation.', 'No treatment needed.', 'Keep monitoring the plants regularly, water at the base, ensure good air circulation and keep fertilization balanced.'),
('Blueberry___healthy', 'Blueberry', 'Healthy', TRUE, NULL, 'The blueberry leaf shows no visible sign of disease.', 'Uniform color and normal shape, with no spots, lesions, mold or deformation.', 'No treatment needed.', 'Keep monitoring the plants regularly, water at the base, ensure good air circulation and keep fertilization balanced.'),
('Cherry_(including_sour)___Powdery_mildew', 'Cherry (including sour)', 'Powdery mildew', FALSE, 'Podosphaera clandestina (fungus)', 'A fungal disease of cherry trees that develops in warm, dry days followed by humid nights.', 'White powdery patches on young leaves. Infected leaves curl and become distorted. Fruit can also be affected.', 'Apply a fungicide approved for cherries, such as a sulfur-based product, and remove heavily infected shoots.', 'Prune to improve air circulation, avoid excess nitrogen fertilization, and avoid overhead irrigation.'),
('Cherry_(including_sour)___healthy', 'Cherry (including sour)', 'Healthy', TRUE, NULL, 'The cherry (including sour) leaf shows no visible sign of disease.', 'Uniform color and normal shape, with no spots, lesions, mold or deformation.', 'No treatment needed.', 'Keep monitoring the plants regularly, water at the base, ensure good air circulation and keep fertilization balanced.'),
('Corn_(maize)___Cercospora_leaf_spot Gray_leaf_spot', 'Corn (maize)', 'Cercospora leaf spot (Gray leaf spot)', FALSE, 'Cercospora zeae-maydis (fungus)', 'A major fungal disease of corn, favored by warm and humid weather and by corn residue left on the field.', 'Narrow, rectangular gray to tan lesions that run parallel to the leaf veins. Lesions merge and can blight entire leaves.', 'Apply a foliar fungicide when the disease reaches the upper leaves around tasseling, following local thresholds.', 'Plant resistant hybrids, rotate crops, and manage corn residue.'),
('Corn_(maize)___Common_rust_', 'Corn (maize)', 'Common rust', FALSE, 'Puccinia sorghi (fungus)', 'A rust disease of corn, favored by cool temperatures and high humidity.', 'Small oval to elongated cinnamon-brown powdery pustules on both sides of the leaves. Pustules turn black late in the season.', 'Usually not needed on resistant hybrids. On susceptible varieties such as sweet corn, apply an approved fungicide when pustules appear early.', 'Plant resistant hybrids and plant early in the season.'),
('Corn_(maize)___Northern_Leaf_Blight', 'Corn (maize)', 'Northern leaf blight', FALSE, 'Exserohilum turcicum (fungus)', 'A fungal disease of corn, favored by moderate temperatures and long periods of leaf wetness.', 'Long cigar-shaped gray-green to tan lesions, from 2.5 to 15 cm, appearing first on the lower leaves.', 'On susceptible hybrids, apply an approved fungicide when lesions appear before tasseling.', 'Plant resistant hybrids, rotate crops, and manage corn residue.'),
('Corn_(maize)___healthy', 'Corn (maize)', 'Healthy', TRUE, NULL, 'The corn (maize) leaf shows no visible sign of disease.', 'Uniform color and normal shape, with no spots, lesions, mold or deformation.', 'No treatment needed.', 'Keep monitoring the plants regularly, water at the base, ensure good air circulation and keep fertilization balanced.'),
('Grape___Black_rot', 'Grape', 'Black rot', FALSE, 'Guignardia bidwellii (fungus)', 'A fungal disease of grapevines that can destroy a large part of the harvest in warm and wet weather.', 'Small reddish-brown circular spots with dark borders and tiny black dots on leaves. Berries shrivel into hard black mummies.', 'Remove mummified berries and infected parts, and apply an approved fungicide from early shoot growth through bloom.', 'Keep the vineyard clean, remove mummified berries, and prune to keep the canopy open.'),
('Grape___Esca_(Black_Measles)', 'Grape', 'Esca (Black measles)', FALSE, 'Fungal complex (Phaeomoniella chlamydospora, Phaeoacremonium spp. and others)', 'A trunk disease of grapevines caused by several fungi that colonize the wood.', 'Tiger-stripe leaves: yellow or red areas between the veins that later dry out. Dark spots on berries. Vines can wilt suddenly.', 'There is no curative treatment. Remove and destroy severely affected vines, or renew the trunk from a healthy shoot.', 'Protect pruning wounds, prune in dry weather, and use healthy planting material.'),
('Grape___Leaf_blight_(Isariopsis_Leaf_Spot)', 'Grape', 'Leaf blight (Isariopsis leaf spot)', FALSE, 'Pseudocercospora vitis (fungus)', 'A fungal leaf disease of grapevines, more frequent in warm and humid regions.', 'Irregular dark red-brown to black spots on leaves, often with a yellow margin. Spots dry out and leaves can fall early.', 'Fungicide programs used against other grape diseases usually control it. Remove infected leaves.', 'Manage the canopy for good air circulation and remove fallen leaves.'),
('Grape___healthy', 'Grape', 'Healthy', TRUE, NULL, 'The grape leaf shows no visible sign of disease.', 'Uniform color and normal shape, with no spots, lesions, mold or deformation.', 'No treatment needed.', 'Keep monitoring the plants regularly, water at the base, ensure good air circulation and keep fertilization balanced.'),
('Orange___Haunglongbing_(Citrus_greening)', 'Orange', 'Huanglongbing (Citrus greening)', FALSE, 'Candidatus Liberibacter asiaticus (bacterium), spread by the Asian citrus psyllid', 'One of the most destructive citrus diseases. It is a quarantine disease in many countries.', 'Asymmetric blotchy yellow mottling of leaves, yellow shoots, and small lopsided bitter fruit that stays green at the bottom. Trees decline over time.', 'There is no cure. Remove infected trees to protect the others, control the psyllid vector, and report suspected cases to the plant protection authorities.', 'Use certified disease-free nursery trees, control psyllids, and inspect trees regularly.'),
('Peach___Bacterial_spot', 'Peach', 'Bacterial spot', FALSE, 'Xanthomonas arboricola pv. pruni (bacterium)', 'A bacterial disease of peach trees, favored by warm, wet and windy weather.', 'Small water-soaked angular spots on leaves that turn purple-brown. Their centers fall out, giving a shot-hole look. Leaves yellow and drop, and fruit can show spots and cracks.', 'Copper-based sprays at specific times can reduce the disease, but must be used carefully because peach leaves are sensitive to copper.', 'Plant resistant varieties, avoid sandy and wind-exposed sites, and keep fertilization balanced.'),
('Peach___healthy', 'Peach', 'Healthy', TRUE, NULL, 'The peach leaf shows no visible sign of disease.', 'Uniform color and normal shape, with no spots, lesions, mold or deformation.', 'No treatment needed.', 'Keep monitoring the plants regularly, water at the base, ensure good air circulation and keep fertilization balanced.'),
('Pepper,_bell___Bacterial_spot', 'Pepper, bell', 'Bacterial spot', FALSE, 'Xanthomonas spp. (bacterium)', 'A bacterial disease of pepper, spread by rain splash, contaminated seed and handling of wet plants.', 'Small water-soaked spots on leaves that turn brown, often with a yellow halo. Leaves drop, and fruit shows raised scabby spots.', 'Remove infected leaves or plants. Copper-based sprays can slow the spread. Avoid working among wet plants.', 'Use certified disease-free seed and transplants, rotate crops for 2 to 3 years, avoid overhead irrigation, and plant resistant varieties.'),
('Pepper,_bell___healthy', 'Pepper, bell', 'Healthy', TRUE, NULL, 'The pepper, bell leaf shows no visible sign of disease.', 'Uniform color and normal shape, with no spots, lesions, mold or deformation.', 'No treatment needed.', 'Keep monitoring the plants regularly, water at the base, ensure good air circulation and keep fertilization balanced.'),
('Potato___Early_blight', 'Potato', 'Early blight', FALSE, 'Alternaria solani (fungus)', 'A common fungal disease of potato, more severe on stressed or older plants.', 'Dark brown spots with concentric rings, like a target, often surrounded by a yellow halo. Older lower leaves are affected first.', 'Apply a fungicide approved for early blight and remove infected leaves.', 'Rotate crops, keep fertilization balanced, avoid plant stress, and remove plant debris and volunteer plants.'),
('Potato___Late_blight', 'Potato', 'Late blight', FALSE, 'Phytophthora infestans (oomycete)', 'A very destructive disease that spreads fast in cool and wet weather. The same pathogen attacks tomato.', 'Pale green water-soaked spots that quickly become dark brown to black. White fuzzy growth appears on the underside in humid conditions. Tubers show a reddish-brown rot.', 'Act quickly: remove and destroy infected plants, do not compost them, and apply a protective fungicide approved for late blight.', 'Use certified seed tubers, destroy cull piles and volunteer plants, plant resistant varieties, and follow disease forecasts.'),
('Potato___healthy', 'Potato', 'Healthy', TRUE, NULL, 'The potato leaf shows no visible sign of disease.', 'Uniform color and normal shape, with no spots, lesions, mold or deformation.', 'No treatment needed.', 'Keep monitoring the plants regularly, water at the base, ensure good air circulation and keep fertilization balanced.'),
('Raspberry___healthy', 'Raspberry', 'Healthy', TRUE, NULL, 'The raspberry leaf shows no visible sign of disease.', 'Uniform color and normal shape, with no spots, lesions, mold or deformation.', 'No treatment needed.', 'Keep monitoring the plants regularly, water at the base, ensure good air circulation and keep fertilization balanced.'),
('Soybean___healthy', 'Soybean', 'Healthy', TRUE, NULL, 'The soybean leaf shows no visible sign of disease.', 'Uniform color and normal shape, with no spots, lesions, mold or deformation.', 'No treatment needed.', 'Keep monitoring the plants regularly, water at the base, ensure good air circulation and keep fertilization balanced.'),
('Squash___Powdery_mildew', 'Squash', 'Powdery mildew', FALSE, 'Podosphaera xanthii (fungus)', 'A very common fungal disease of squash and other cucurbits.', 'White powdery spots on both sides of the leaves that spread until they cover them. Leaves turn yellow and dry out.', 'At the first signs, apply an approved product such as sulfur or potassium bicarbonate, and remove badly infected leaves.', 'Plant resistant varieties, space plants for air circulation, and grow them in full sun.'),
('Strawberry___Leaf_scorch', 'Strawberry', 'Leaf scorch', FALSE, 'Diplocarpon earlianum (fungus)', 'A fungal leaf disease of strawberry that weakens plants and reduces yield.', 'Many small irregular purple spots on the upper side of leaves. The spots merge and leaves look scorched, then dry and curl.', 'Remove infected leaves after harvest and apply an approved fungicide if the disease is severe.', 'Plant resistant varieties, avoid overhead irrigation, renovate beds after harvest, and keep good spacing.'),
('Strawberry___healthy', 'Strawberry', 'Healthy', TRUE, NULL, 'The strawberry leaf shows no visible sign of disease.', 'Uniform color and normal shape, with no spots, lesions, mold or deformation.', 'No treatment needed.', 'Keep monitoring the plants regularly, water at the base, ensure good air circulation and keep fertilization balanced.'),
('Tomato___Bacterial_spot', 'Tomato', 'Bacterial spot', FALSE, 'Xanthomonas spp. (bacterium)', 'A bacterial disease of tomato, spread by rain splash, contaminated seed and handling of wet plants.', 'Small dark water-soaked spots on leaves, often with a yellow halo. Fruit shows small raised scabby spots.', 'Remove infected leaves. Copper-based sprays can slow the spread. Avoid working among wet plants.', 'Use certified disease-free seed and transplants, rotate crops, and avoid overhead irrigation.'),
('Tomato___Early_blight', 'Tomato', 'Early blight', FALSE, 'Alternaria solani (fungus)', 'A common fungal disease of tomato that starts on the older leaves.', 'Brown spots with concentric rings, like a target, surrounded by yellow tissue. Dark lesions can appear on the stem near the soil and on fruit near the stem.', 'Remove infected lower leaves and apply an approved fungicide.', 'Rotate crops, mulch the soil, stake plants, and water at the base with drip irrigation.'),
('Tomato___Late_blight', 'Tomato', 'Late blight', FALSE, 'Phytophthora infestans (oomycete)', 'A very destructive disease that spreads fast in cool and wet weather. The same pathogen attacks potato.', 'Large irregular greasy gray-green to brown lesions on leaves, with white mold on the underside in humid weather. Fruit shows firm brown rot.', 'Remove and destroy infected plants quickly and apply a protective fungicide approved for late blight.', 'Avoid wetting the leaves, space plants well, plant resistant varieties, and do not plant near infected potatoes.'),
('Tomato___Leaf_Mold', 'Tomato', 'Leaf mold', FALSE, 'Passalora fulva (fungus)', 'A fungal disease of tomato, mainly in greenhouses and other places with high humidity.', 'Pale green to yellow spots on the upper side of leaves, with an olive-green to brown velvety mold on the underside.', 'Lower the humidity with ventilation, remove infected leaves, and apply an approved fungicide.', 'Keep humidity below 85 percent, ventilate greenhouses, space plants, and plant resistant varieties.'),
('Tomato___Septoria_leaf_spot', 'Tomato', 'Septoria leaf spot', FALSE, 'Septoria lycopersici (fungus)', 'A fungal leaf disease of tomato that can cause heavy leaf loss.', 'Many small round spots of 2 to 3 mm with dark borders and gray or tan centers containing tiny black dots. Lower leaves are affected first.', 'Remove infected leaves and apply an approved fungicide.', 'Rotate crops, mulch the soil, avoid overhead watering, and remove plant debris.'),
('Tomato___Spider_mites Two-spotted_spider_mite', 'Tomato', 'Spider mites (Two-spotted spider mite)', FALSE, 'Tetranychus urticae (mite pest)', 'Not a disease but a tiny pest that feeds on leaves, mostly in hot and dry conditions.', 'Fine yellow or white speckling on leaves, bronzing, and fine webbing on the underside.', 'Spray water to dislodge the mites, use insecticidal soap or horticultural oil, or an approved miticide. Predatory mites can be used as biological control.', 'Avoid water stress and dusty conditions, check the underside of leaves regularly, and avoid broad-spectrum insecticides that kill natural predators.'),
('Tomato___Target_Spot', 'Tomato', 'Target spot', FALSE, 'Corynespora cassiicola (fungus)', 'A fungal disease of tomato, favored by warm and humid weather. It can look like early blight.', 'Small brown spots that grow into lesions with concentric rings and light centers. Fruit can also show spots.', 'Remove infected leaves and apply an approved fungicide.', 'Improve air circulation, avoid long periods of leaf wetness, rotate crops, and remove plant debris.'),
('Tomato___Tomato_Yellow_Leaf_Curl_Virus', 'Tomato', 'Tomato yellow leaf curl virus', FALSE, 'Begomovirus, transmitted by the whitefly Bemisia tabaci', 'A viral disease spread by whiteflies that can cause severe yield losses.', 'Leaves curl upward and cup, with yellow margins. Leaves are small, plants are stunted, flowers drop and few fruit develop.', 'There is no cure. Remove infected plants in closed bags and control whiteflies.', 'Plant resistant varieties, use insect-proof nets in greenhouses, use yellow sticky traps, control weeds, and use whitefly-free transplants.'),
('Tomato___Tomato_mosaic_virus', 'Tomato', 'Tomato mosaic virus', FALSE, 'Tomato mosaic virus (Tobamovirus)', 'A very stable virus spread by hands, tools and seeds.', 'Light and dark green mosaic pattern on leaves, distorted fern-like leaves, stunted plants, and uneven fruit ripening.', 'There is no cure. Remove and destroy infected plants, and disinfect tools and hands.', 'Use certified seed, plant resistant varieties, wash hands and disinfect tools, and avoid handling tobacco near plants.'),
('Tomato___healthy', 'Tomato', 'Healthy', TRUE, NULL, 'The tomato leaf shows no visible sign of disease.', 'Uniform color and normal shape, with no spots, lesions, mold or deformation.', 'No treatment needed.', 'Keep monitoring the plants regularly, water at the base, ensure good air circulation and keep fertilization balanced.')
