-- Disease information for the 38 classes of the model.
-- class_name must match models/class_names.json exactly.
-- Runs at every startup: existing rows are updated, missing rows are inserted.
AS new ON DUPLICATE KEY UPDATE
  plant = new.plant, disease_name = new.disease_name, healthy = new.healthy, pathogen = new.pathogen,
  description = new.description, symptoms = new.symptoms, treatment = new.treatment, prevention = new.prevention;
